    // Extract all IRX to files
    for ( i = 3; i < nb_entries; i++ ) {
      if ( verbose )
        verbose_print_extract_message( entry[i].name, entry[i].irx_size );
      write_file( entry[i].name, entry[i].irx_binary, entry[i].irx_size );
    }
  }
}


