    irx_updated = PAD16( irx_updated );
    new_irx_size = PAD16( new_irx_size );
    if ( entry[i].name[0] == -1 ) {
      // this entry must be deleted
      if ( i > 2 )
        irx_original += romdir_entry[i].size;
      extinfo_original += romdir_entry[i].extinfo_size;
      romdir_original += sizeof( romdir_t );
